package com.votehub.controller;
import com.votehub.service.ElectionService;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/elections") @CrossOrigin(origins="http://localhost:5173") public class ElectionController {final ElectionService s;ElectionController(ElectionService x){s=x;} @GetMapping public Object all(){return s.all();} @GetMapping("/{id}") public Object one(@PathVariable Long id){return Map.of("election",s.one(id),"candidates",s.candidates(id));} @GetMapping("/{id}/room") public Object room(@PathVariable Long id,@RequestHeader("Authorization") String h){return s.room(id,h.replace("Bearer ",""));} @GetMapping("/{id}/results") public Object results(@PathVariable Long id){return s.results(id);} @PostMapping("/{id}/vote") public Object vote(@PathVariable Long id,@RequestParam Long candidateId,@RequestHeader("Authorization") String h){return s.cast(id,candidateId,h.replace("Bearer ",""));} @GetMapping("/{id}/stream") public org.springframework.web.servlet.mvc.method.annotation.SseEmitter stream(@PathVariable Long id){org.springframework.web.servlet.mvc.method.annotation.SseEmitter e=new org.springframework.web.servlet.mvc.method.annotation.SseEmitter(0L);try{e.send(Map.of("electionId",id,"message","Live channel connected"));}catch(Exception x){e.completeWithError(x);}return e;}}
